export function testParsing(
  URL: new (
    input: string,
    base?: string,
  ) => { href: string; host: string; hostname: string },
) {
  for (const [input, base, operation, expected] of vectors) {
    let result: string;
    try {
      if (operation === "ctor") result = new URL(input, base ?? undefined).href;
      else {
        const url = new URL(base!);
        url[operation] =
          operation === "href" ? "http://" + input + "/p" : input;
        result = url.href;
      }
    } catch (error) {
      result = (error as Error).name;
    }
    strictEqual(
      result,
      expected,
      `${operation}(${JSON.stringify(input)},${JSON.stringify(base)})`,
    );
  }
}
